\addplot[blue, thick, domain=2:6] {sqrt(x^2 - 4)};
\addplot[blue, thick, domain=2:6] {-sqrt(x^2 - 4)};
\addplot[blue, thick, domain=-6:-2] {sqrt(x^2 - 4)};
\addplot[blue, thick, domain=-6:-2] {-sqrt(x^2 - 4)};

\end{axis}
\end{tikzpicture}

